const verified = new Set();
for (const item of inline) {
  if ("'!item.name || !item.name.includes('"'query results')) continue;
  const content = item.content || '';
  for (const line of content.split(/\\r?\\n/)) {
    if ("'!line || line.startsWith('"'peptide\\t')) continue;
    const f = line.split('\\t');
    if (f.length >= 4 && Number(f[2]) < 0.05 && f[3] === '1') verified.add(f[0]);
  }
}
function tsvRows(file) {
  return fs.readFileSync(file, 'utf8').split(/\\r?\\n/).filter(Boolean).map(x => x.split('\\t'));
}
const mqFile = 'data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular';
const sgFile = 'data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular';
const mq = tsvRows(mqFile);
const sg = tsvRows(sgFile);
const raw = new Map();
function add(pep, source, val) {
  if ("'!verified.has(pep)) return;
  if (!raw.has(pep)) raw.set(pep, []);
  raw.get(pep).push({source, val});
}
for (let i = 1; i < mq.length; i++) if (verified.has(mq[i][0])) add(mq[i][0], '"'MaxQuant', mq[i][34] || '');
for (let i = 1; i < sg.length; i++) if (verified.has(sg[i][5])) add(sg[i][5], 'SGPS', sg[i][1] || '');
console.log('verified_count\\t' + verified.size);
console.log('mapped_count\\t' + [...verified].filter(p => raw.has(p)).length);
console.log('unmapped_count\\t' + [...verified].filter(p => "'!raw.has(p)).length);
console.log('"'---RAW---');
for (const pep of [...verified].sort()) {
  console.log(pep + '\\t' + (raw.has(pep) ? raw.get(pep).map(x => x.source + ':' + x.val).join(' || ') : 'NO_REPORT_ROW'));
}
NODE"

